actions.script:
const started = ec.service.sync().name('org.moqui.maps.GeoDataServices.start#GeoDataImport').parameters({dataSetId: dataSetId || null,
    countryGeoId: context.countryGeoId || null, file: context.file || null, force: context.force === 'Y' || context.force === 'true'}).call() || {}
if (!ec.message.hasError()) ec.message.addMessage(started.jobRunId
    ? ec.resource.expand(ec.l10n.localize('Import ${id} started in the background: you are notified when it ends.'), '', {id: started.geoDataImportId})
    : ec.l10n.localize('The import did not start: see its run below.'), started.jobRunId ? 'success' : 'warning')
